import { RevisionCard } from '../revisionDeck';

// Fact cards for modules 19-23, ids mf-<module>-<3-digit sequence>.
// Each card holds ONE atomic fact (minimum-information principle), with an
// active-recall cue on the front. Authored from the app's assignment19-23
// question bank (questions, correct answers and explanations), complementary
// to the existing revisionDeck entries (rev-118 to rev-145) for these modules.
//
// Ids 001-050 preserve the original card themes. Where a single original card
// packed two or more independent facts, the extra facts were split out as
// ids -101, -102, ... (no collision with -001 to -050).

export const MODULE_FLASHCARDS_SLICE: Record<number, RevisionCard[]> = {
  // ---- Module 19: Ethical framework for health research ----
  19: [
    { id: 'mf-19-001', module: 19, front: "CIOMS — full form and role", back: "Council for International Organizations of Medical Sciences — issues international ethical guidelines for research involving humans; a recognised research-ethics framework." },
    { id: 'mf-19-002', module: 19, front: "Bhore report — role", back: "A 1943 Indian health-services planning report; it is NOT a research-ethics document (unlike Nuremberg, Helsinki and CIOMS)." },
    { id: 'mf-19-003', module: 19, front: "Nuremberg Code — what it first introduced", back: "Discussion of the rationale of RISK-BENEFIT analysis and of VOLUNTARY CONSENT in research (1947)." },
    { id: 'mf-19-004', module: 19, front: "Belmont Report — originating study", back: "The Tuskegee syphilis study (USA), which prompted the Belmont Report of 1979." },
    { id: 'mf-19-005', module: 19, front: "Ethics review — which studies need it", back: "ALL research with human participants or their data — lab tests (e.g. HIV prevalence), questionnaire-only studies, secondary-data analyses and archived data. No design is exempt." },
    { id: 'mf-19-006', module: 19, front: "Informed consent not needed — which data are exempt", back: "Research on already-available AGGREGATE data, e.g. analysis of mortality data of 2001-2010. Outbreak investigation and verbal autopsy still need consent." },
    { id: 'mf-19-007', module: 19, front: "Informed consent document — which items belong", back: "Study procedures · potential risks and benefits · compensation and post-trial access to care · contact details of the Principal Investigator." },
    { id: 'mf-19-008', module: 19, front: "Participant information sheet — mandatory contact", back: "The contact information of the Principal Investigator is mandatory in the information sheet." },
    { id: 'mf-19-009', module: 19, front: "Consent obtained by coercion", back: "INVALID — it violates the principle of autonomy; informed consent must be freely given." },
    { id: 'mf-19-010', module: 19, front: "'Encouraging the person to consent'", back: "NOT part of the informed consent process — the participant must decide freely; the process covers confidentiality, risks/benefits and compensation for lost wages." },
    { id: 'mf-19-011', module: 19, front: "Undue inducement — definition", back: "Offering something excessive that pushes a person to participate against better judgment — e.g. giving refrigerators to participant families in a vaccine trial." },
    { id: 'mf-19-012', module: 19, front: "Reimbursement vs undue inducement", back: "Reimbursing travel, food and lost daily wages raises NO ethical question; payment to ENCOURAGE participation is not permissible." },
    { id: 'mf-19-013', module: 19, front: "Autonomy — how it is breached", back: "Pressurising a participant to continue after they wish to withdraw, or giving insufficient information; autonomy underlies voluntary participation and the right to withdraw." },
    { id: 'mf-19-014', module: 19, front: "Beneficence", back: "The duty to DO GOOD — maximise the possible benefits of the research for participants and society." },
    { id: 'mf-19-015', module: 19, front: "Non-maleficence", back: "'Do no harm' — the researcher must avoid harming participants and ensure the good outweighs possible harm." },
    { id: 'mf-19-016', module: 19, front: "Justice — how it is breached", back: "Unfair selection or exclusion (e.g. dropping a gender or ethnic group without valid scientific reason), or unfairness linked to socio-demographic or cultural factors." },
    { id: 'mf-19-017', module: 19, front: "Right to withdraw — which principle", back: "AUTONOMY — a participant may withdraw at any time, even midway, without penalty or giving reasons." },
    { id: 'mf-19-018', module: 19, front: "Consent documentation — who may verify it", back: "Study monitors, regulators and ethics committee members all have the authority to verify participants' consent documentation." },
    { id: 'mf-19-019', module: 19, front: "IEC — core responsibilities", back: "Protect participants' rights · evaluate potential community benefit of the study · re-evaluate the study when modified." },
    { id: 'mf-19-020', module: 19, front: "IEC — what is NOT its job", back: "Sanctioning funding for the study, and advocating for it in the community. Novelty, researcher competence and research relevance DO fall within ethical review." },
    { id: 'mf-19-021', module: 19, front: "IEC composition — size and chairperson (ICMR 2017)", back: "Minimum 7 members; chairperson from OUTSIDE the institution; a member secretary." },
    { id: 'mf-19-102', module: 19, front: "IEC composition — required members", back: "At least one layperson and one woman, plus members from medical, non-medical, scientific and non-scientific backgrounds." },
    { id: 'mf-19-022', module: 19, front: "IEC continuing review", back: "Approval is not one-off: the IEC re-reviews ongoing studies at least annually and must re-review every protocol modification." },
    { id: 'mf-19-023', module: 19, front: "Expedited review — when permitted", back: "ICMR 2017 allows a shorter (expedited) review by designated members for research of no more than MINIMAL risk; higher risk goes to the full committee." },
    { id: 'mf-19-024', module: 19, front: "Waiver of informed consent — who approves", back: "The IEC may waive individual consent for research using only existing records/secondary data where consent is impracticable; the waiver itself needs committee approval." },
    { id: 'mf-19-025', module: 19, front: "Group consent (tribal communities)", back: "Consent from the tribal head is DESIRABLE but does NOT replace individual consent." },
    { id: 'mf-19-026', module: 19, front: "Individual consent in tribal research", back: "Every participant still gives individual informed consent even when group consent has been obtained." },
    { id: 'mf-19-103', module: 19, front: "Women in tribal research consent", back: "Women CANNOT be excluded from the informed consent process; confidentiality requirements apply in full." },
    { id: 'mf-19-027', module: 19, front: "Assent vs consent", back: "Consent = legally valid agreement by an adult (18 years or more). Assent = a minor's agreement, since a minor cannot legally consent." },
    { id: 'mf-19-028', module: 19, front: "Research in children — consent rules", back: "Below 18 years, obtain consent from a parent or legally acceptable representative PLUS age-appropriate assent from the child." },
    { id: 'mf-19-029', module: 19, front: "Adolescent study (12-15 years) — what is NOT taken", back: "Consent FROM the participant is NOT taken (a minor cannot consent); required are the participant's assent and the parent's consent." },
    { id: 'mf-19-030', module: 19, front: "LAR — full form and meaning", back: "Legally Acceptable Representative — the person who gives consent on behalf of a participant who cannot consent themselves." },
    { id: 'mf-19-031', module: 19, front: "Vulnerable populations — examples", back: "Children · pregnant women · prisoners · economically/educationally disadvantaged · mentally ill or incapacitated · tribal communities — all needing extra safeguards." },
    { id: 'mf-19-032', module: 19, front: "Illiterate participant — how consent is recorded", back: "The information sheet is read out and the participant gives a THUMB IMPRESSION." },
    { id: 'mf-19-104', module: 19, front: "Illiterate participant — witness requirement", back: "An IMPARTIAL WITNESS must be present during the informed consent process." },
    { id: 'mf-19-105', module: 19, front: "Illiterate participant — who must NOT sign", back: "The field investigator must NOT sign on the participant's behalf; consent cannot be skipped." },
    { id: 'mf-19-033', module: 19, front: "Impartial witness — who qualifies", back: "Any LITERATE person who is NOT part of the study (not a research-team member, not an illiterate family member) who witnesses and signs." },
    { id: 'mf-19-034', module: 19, front: "Consent — process and timing", back: "A PROCESS, not a one-time signature: obtained BEFORE any data collection and it can be repeated or re-affirmed during the study." },
    { id: 'mf-19-035', module: 19, front: "Consent — language", back: "Information must be conveyed in a language the participant UNDERSTANDS (local language), verbally and in writing." },
    { id: 'mf-19-036', module: 19, front: "Compensation for trial-related injury", back: "Compensation IS offered for trial-related injury; wage loss and travel expenses may also be compensated." },
    { id: 'mf-19-037', module: 19, front: "Payment to encourage participation", back: "NOT permissible — money must never push participation; only travel, food, lost wages and injury compensation are legitimate." },
    { id: 'mf-19-038', module: 19, front: "Adherence to the approved protocol", back: "LACK of adherence is unethical; any deviation needs IEC approval through a formal amendment." },
    { id: 'mf-19-039', module: 19, front: "Genetic research — which frameworks apply", back: "Both the ICMR ethical guidelines AND the policy on genome/genetic research (even for a private research institute)." },
    { id: 'mf-19-040', module: 19, front: "Confidentiality — ethics link", back: "Assurance of confidentiality is part of consent; disclosing a participant's identity breaches confidentiality and participant rights." },
    { id: 'mf-19-041', module: 19, front: "Archived/available data — ethics review", back: "Essential even when already-available or archived data are used for research." },
    { id: 'mf-19-042', module: 19, front: "Interview-based research — IEC review", back: "Required — interview-based research is NOT exempt from ethics committee approval." },
    { id: 'mf-19-043', module: 19, front: "IEC and the publication plan", back: "The IEC DOES review the publication/dissemination plan along with the research proposal." },
    { id: 'mf-19-044', module: 19, front: "Declaration of Helsinki — overriding principle", back: "The interests of science and society must NEVER take precedence over the well-being of the individual research participant." },
    { id: 'mf-19-045', module: 19, front: "ICMR 2017 — what changed", back: "The 2017 National Ethical Guidelines replaced the 2006 norms and shifted the language from 'human subjects' to 'human PARTICIPANTS'." },
    { id: 'mf-19-046', module: 19, front: "Records retention — observational study (ICMR 2017)", back: "Case report forms/records should be preserved for 3 YEARS." },
    { id: 'mf-19-047', module: 19, front: "Post-trial provisions in consent", back: "The consent document must describe post-trial access to care/proven interventions and compensation arrangements." },
    { id: 'mf-19-048', module: 19, front: "Compensation details — which document", back: "The informed consent document carries details of compensation (including trial-related injury) and post-trial access to care." },
    { id: 'mf-19-049', module: 19, front: "Belmont Report — what it guides", back: "The procedure of informed consent · the basic ethical principles (autonomy, beneficence, justice) · the need for ethics-committee review." },
    { id: 'mf-19-050', module: 19, front: "Insufficient information — which principle is breached", back: "AUTONOMY — conveying insufficient information prevents an informed voluntary decision." },
    { id: 'mf-19-106', module: 19, front: "Trials involving newborns — is assent required", back: "No — assent is NOT required for newborns/young infants; consent from a parent is taken instead." },
    { id: 'mf-19-101', module: 19, front: "Informed consent document — which item is excluded", back: "The study BUDGET does not belong in the informed consent document." }
  ],

  // ---- Module 20: Conducting clinical trials ----
  20: [
    { id: 'mf-20-001', module: 20, front: "Randomized Controlled Trial (RCT)", back: "A study design in which participants are RANDOMLY assigned to an experimental (intervention) group or a control group." },
    { id: 'mf-20-002', module: 20, front: "Randomization — definition", back: "Allocating treatment such that each subject has an EQUAL CHANCE of receiving any possible treatment — balances known and unknown prognostic factors between arms." },
    { id: 'mf-20-003', module: 20, front: "Allocation concealment", back: "Keeping the randomization sequence hidden from those enrolling participants until the moment of allocation — prevents manipulation of treatment assignment." },
    { id: 'mf-20-004', module: 20, front: "Blinding — levels", back: "Open label (none) · single (participant OR assessor unaware) · double (participant AND investigator unaware) · triple (analyst/monitor also unaware)." },
    { id: 'mf-20-005', module: 20, front: "Double blinding — classic application", back: "Comparing a new drug with a standard drug where NEITHER the participant NOR the treating investigator knows who receives which drug." },
    { id: 'mf-20-006', module: 20, front: "Blinding — which bias it does NOT eliminate", back: "SELECTION bias. Blinding reduces information (observation) bias; selection bias in an RCT is handled by randomization." },
    { id: 'mf-20-007', module: 20, front: "RCT — advantages", back: "Effectively controls confounding · provides a high level of evidence · can be conducted in the community or in hospital." },
    { id: 'mf-20-101', module: 20, front: "RCT — bias it uniquely overcomes", back: "It is the only design that effectively overcomes SELECTION bias in the allocation of participants." },
    { id: 'mf-20-008', module: 20, front: "RCT — limitations", back: "Not a simple, uncomplicated or unregulated design · often requires a LARGE sample size · regulatory and ethics oversight are mandatory." },
    { id: 'mf-20-102', module: 20, front: "RCT — generalizability limitation", back: "Results are not always readily generalizable because of strict eligibility (inclusion/exclusion) criteria." },
    { id: 'mf-20-009', module: 20, front: "Screening protocol of a trial", back: "Interested persons are interviewed and may undergo medical examination; investigators explain procedures and criteria; ELIGIBILITY is determined at screening." },
    { id: 'mf-20-010', module: 20, front: "Consent timing in a trial", back: "Informed consent must be obtained PRIOR to participation — never after the trial has started or at any later point." },
    { id: 'mf-20-011', module: 20, front: "Clinical trial monitoring — scope", back: "Adherence to Good Clinical Practice · documentation of informed consent, randomization and study-product administration · adverse-event reporting." },
    { id: 'mf-20-012', module: 20, front: "GCP — full form and purpose", back: "Good Clinical Practice — an international quality standard for designing, conducting, recording and reporting trials, protecting participants and ensuring credible data." },
    { id: 'mf-20-013', module: 20, front: "DSMB — who appoints it", back: "The SPONSOR (or overseeing body), not the investigators; the DSMB must be INDEPENDENT of the trial team." },
    { id: 'mf-20-014', module: 20, front: "DSMB — functions", back: "Periodically reviews accumulated data for participant safety, conduct and progress · recommends CONTINUATION, MODIFICATION or TERMINATION of the trial." },
    { id: 'mf-20-015', module: 20, front: "DSMB — what it does NOT do", back: "It does NOT decide the randomization sequence or manage the trial day-to-day — it is an independent advisory/oversight entity." },
    { id: 'mf-20-016', module: 20, front: "Interim analysis", back: "Analysis of accumulating data DURING the trial, permitted only if PRE-STATED in the protocol; reviewed by the DSMB." },
    { id: 'mf-20-017', module: 20, front: "Adverse event (AE) — definition", back: "Any unexpected clinical/familial/social problem occurring during treatment in a trial — with NO judgment about causality; it need not be caused by the study product." },
    { id: 'mf-20-018', module: 20, front: "Serious adverse event (SAE)", back: "An adverse event causing death, that is life-threatening, requires hospitalization or its prolongation, or causes persistent disability/incapacity." },
    { id: 'mf-20-019', module: 20, front: "Managing a serious adverse event", back: "Provide FREE treatment for the affected participant · inform the regulatory authorities · withdraw the implicated intervention. Action is required regardless of the percentage affected." },
    { id: 'mf-20-020', module: 20, front: "AE vs SAE", back: "AE = any untoward occurrence during the trial, no causality judgment. SAE = an AE meeting seriousness criteria (death, life-threatening, hospitalization, disability)." },
    { id: 'mf-20-021', module: 20, front: "AE assessment — key element", back: "The TEMPORAL relationship between administration of the study product and occurrence of the adverse event." },
    { id: 'mf-20-022', module: 20, front: "Adverse events — NOT reported to", back: "The Scientific Advisory Committee. AEs ARE reported to the regulatory authority, the sponsor and the Institutional Ethics Committee." },
    { id: 'mf-20-023', module: 20, front: "Valid reasons for premature trial stoppage", back: "A significant UNANTICIPATED risk is demonstrated, or results show no justification for exposing participants to further potential risk." },
    { id: 'mf-20-024', module: 20, front: "Placebo-controlled trial — ethics", back: "It is UNETHICAL to use a placebo in the control arm instead of the CURRENT STANDARD OF CARE when a proven effective therapy exists." },
    { id: 'mf-20-025', module: 20, front: "Biological samples — consent clause", back: "The participant information sheet must contain a clause on the collection, storage and use of biological samples for research purposes." },
    { id: 'mf-20-026', module: 20, front: "Consent documentation in trials", back: "Written (signed) informed consent is required, and one copy of the signed consent form is given to the participant." },
    { id: 'mf-20-027', module: 20, front: "Reimbursements — no ethical problem", back: "Reimbursing participants for TIME spent, travel cost, food expenses and loss of daily wages is ethically acceptable in trials." },
    { id: 'mf-20-028', module: 20, front: "Reimbursement vs compensation (trials)", back: "Reimbursement covers expenses (travel, food, wages) for ALL participants; compensation is payment for DAMAGE/injury and is given only if damage has occurred." },
    { id: 'mf-20-029', module: 20, front: "Trial analysis — first step", back: "Baseline characteristics of participants should be COMPARED ACROSS STUDY ARMS to confirm randomization produced comparable groups." },
    { id: 'mf-20-030', module: 20, front: "Intention-to-treat (ITT)", back: "Participants are analysed in the arm to which they were randomized, REGARDLESS of adherence; those lost to follow-up can be included." },
    { id: 'mf-20-031', module: 20, front: "Trial document archival", back: "Trial-related documents must be ARCHIVED — commonly for 5-15 years as per the sponsor's requirement; computerized data does not remove this need." },
    { id: 'mf-20-032', module: 20, front: "Regulatory access to trial data", back: "The investigator does NOT have the right to refuse to show trial data — regulatory authorities must be granted access to records and source documents." },
    { id: 'mf-20-033', module: 20, front: "IEC clearance — after initial approval", back: "It CAN be withdrawn or cancelled after initial approval, e.g. for safety violations." },
    { id: 'mf-20-034', module: 20, front: "Scientific review committee — primary function", back: "Checking whether the research METHODS are appropriate. It is NOT responsible for participant safety and welfare — that is the IEC's domain." },
    { id: 'mf-20-035', module: 20, front: "Scientific Advisory Committee — role limit", back: "It does NOT examine the safety and welfare of trial participants; its domain is scientific merit." },
    { id: 'mf-20-036', module: 20, front: "Trial protocol review — critical focus", back: "To ensure participant safety and welfare, the protocol is critically reviewed for ETHICAL issues (by the ethics committee)." },
    { id: 'mf-20-037', module: 20, front: "Ethically appropriate trial — minimum", back: "Participants must give informed VOLUNTARY consent before enrollment; ethics-committee approval and prospective trial registration are also mandatory." },
    { id: 'mf-20-038', module: 20, front: "Clinical trial phases I-III", back: "Phase I — safety/dosage, usually healthy volunteers · Phase II — efficacy and dose-finding in patients · Phase III — large comparison with standard care/placebo, monitoring adverse events." },
    { id: 'mf-20-039', module: 20, front: "Phase IV trial", back: "Post-marketing surveillance AFTER a drug is approved and marketed — monitors long-term safety and rare adverse effects in the general population." },
    { id: 'mf-20-040', module: 20, front: "Control arm choices", back: "Placebo (only when NO proven effective therapy exists) or ACTIVE control — the current standard of care. Using placebo against proven therapy is unethical." },
    { id: 'mf-20-041', module: 20, front: "Trial investigator — duties", back: "Obtain written informed consent before participation · follow the approved protocol · report adverse events · maintain and archive trial documents." },
    { id: 'mf-20-042', module: 20, front: "IEC in trials — what it decides", back: "Reviews the trial protocol for participant safety and welfare, and decides matters of REIMBURSEMENT and COMPENSATION for research participants." },
    { id: 'mf-20-043', module: 20, front: "Trial sequence", back: "Screening (eligibility) → enrollment (consent) → randomization/allocation → intervention and follow-up → interim analyses → final analysis and reporting." },
    { id: 'mf-20-044', module: 20, front: "Randomization vs blinding", back: "Randomization = HOW participants are ALLOCATED to arms (prevents selection bias). Blinding = WHO knows the allocation (prevents information bias)." },
    { id: 'mf-20-045', module: 20, front: "Trial stoppage rules — purpose", back: "Pre-specified stopping guidelines based on observed toxicity/adverse-event rates are the MOST COMMON method of preventing potential harm to participants." },
    { id: 'mf-20-046', module: 20, front: "Clinical trials — review levels", back: "Review at MULTIPLE levels: scientific review, ethics (IEC) review and regulatory review (DCGI/HMSC), plus ongoing monitoring." },
    { id: 'mf-20-047', module: 20, front: "Study-product administration — documentation", back: "Administration of the study product (dose, timing, adherence) must be DOCUMENTED for every participant — a routine trial-monitoring item." },
    { id: 'mf-20-048', module: 20, front: "Open-label trial", back: "A trial with NO blinding — the participant, the investigator and everyone else know which treatment is assigned." },
    { id: 'mf-20-049', module: 20, front: "Adverse events — the DSMB's view", back: "Accumulated adverse-event data are also periodically reviewed by the DSMB, a legitimate oversight recipient of AE data." },
    { id: 'mf-20-050', module: 20, front: "Placebo — definition", back: "An inert substance or sham procedure with no therapeutic effect, given to the control group so the intervention's effect can be measured without bias." },
    { id: 'mf-20-103', module: 20, front: "DCGI and HMSC — kind of review", back: "Drug Controller General of India and Health Ministry Screening Committee conduct REGULATORY review of clinical trials." },
    { id: 'mf-20-104', module: 20, front: "Scientific review — which body", back: "The scientific review committee performs scientific review; the Institutional Governing Board is NOT responsible for it." },
    { id: 'mf-20-105', module: 20, front: "Preventing participant harm — method that is NOT valid", back: "Close watch on enrolment targets. Genuine methods: AE/SAE reporting, DSMB review, and regular monitoring by a pre-identified monitoring agency." },
    { id: 'mf-20-106', module: 20, front: "Internationally funded project — regulatory affairs body", back: "The Health Ministry Screening Committee (HMSC) looks at the regulatory affairs of internationally funded research projects." },
    { id: 'mf-20-107', module: 20, front: "Independent ethics committees — who uses them", back: "Researchers who have no institutional affiliation can use independent ethics committees that function outside institutions." },
    { id: 'mf-20-108', module: 20, front: "Consent documentation in trials — verbal consent", back: "Verbal consent alone is NOT sufficient for conducting a trial; written informed consent is required." }
  ],

  // ---- Module 21: Preparing a concept paper ----
  21: [
    { id: 'mf-21-001', module: 21, front: "Concept paper — definition", back: "A CONCISE SUMMARY of the planned research project — not a detailed protocol, and not written after the study." },
    { id: 'mf-21-002', module: 21, front: "Concept paper vs protocol — order", back: "The concept paper is written FIRST; the full protocol is drafted later using it as the outline." },
    { id: 'mf-21-003', module: 21, front: "Concept paper — components", back: "Title · Background & Justification · Objectives · Methods · Expected Benefits · Ethics · Budget · Key references." },
    { id: 'mf-21-004', module: 21, front: "Conclusion in a concept paper", back: "Not a component — neither are Discussion, Abstract or Results." },
    { id: 'mf-21-005', module: 21, front: "Discussion in a concept paper", back: "Not a component — it carries no findings, since the study is only planned." },
    { id: 'mf-21-006', module: 21, front: "Abstract in a concept paper", back: "Not a component; the components are Title, Background & Justification, Objectives, Methods, Expected Benefits, Ethics, Budget and References." },
    { id: 'mf-21-007', module: 21, front: "Detailed results in a concept paper", back: "Never included — a concept paper describes a PLANNED study, so detailed results, data analysis and discussion must not appear." },
    { id: 'mf-21-008', module: 21, front: "Annotated bibliography in a concept paper", back: "Not a component; references are given in a standard format instead." },
    { id: 'mf-21-009', module: 21, front: "Concept paper — recommended style", back: "A concise document · presented mostly in BULLET form · a RESTRICTED (limited) number of objectives." },
    { id: 'mf-21-010', module: 21, front: "Methods detail in a concept paper", back: "Methods should NOT be described in detail — that is reserved for the full protocol." },
    { id: 'mf-21-011', module: 21, front: "Concept paper — agency use", back: "Funding agencies use the concept paper to SCREEN the proposal for funding, before asking for a full protocol." },
    { id: 'mf-21-012', module: 21, front: "Advantages of writing a concept paper", back: "You organise your ideas AND may stand out and receive a positive response from reviewers." },
    { id: 'mf-21-013', module: 21, front: "Concept paper — funding guarantee", back: "None — it improves the idea and the chances with reviewers, but funding is never assured." },
    { id: 'mf-21-014', module: 21, front: "'Background & Justification' — sequence", back: "1) Importance of the study problem → 2) known and unknown aspects of the problem → 3) information needed to address the problem effectively." },
    { id: 'mf-21-015', module: 21, front: "Background — importance of the problem", back: "The FIRST element of Background & Justification: why the health problem is important." },
    { id: 'mf-21-016', module: 21, front: "Background — known facts", back: "State what is KNOWN about the problem — in relation to the LOCAL CONTEXT, not only the global literature." },
    { id: 'mf-21-017', module: 21, front: "Background — the unknown/gap", back: "State what is UNKNOWN in the literature — the knowledge gap that the proposed research will fill." },
    { id: 'mf-21-018', module: 21, front: "Background — what it does NOT include", back: "The prior contribution of the researcher on the topic, and the policy/practice implications of the proposed study." },
    { id: 'mf-21-019', module: 21, front: "'What is known and unknown' — which section", back: "Background & Justification." },
    { id: 'mf-21-020', module: 21, front: "Policy implications — which section", back: "'Expected Benefits' — NOT the Background." },
    { id: 'mf-21-021', module: 21, front: "Knowledge gap — role", back: "The gap identified in the Background justifies the study and is the bridge leading into the objectives." },
    { id: 'mf-21-022', module: 21, front: "Justification — what it argues", back: "WHY this study is needed now: the importance of the problem PLUS the knowledge gap the proposed research will fill." },
    { id: 'mf-21-023', module: 21, front: "First step in writing a proposal", back: "Framing the study OBJECTIVES — the first step for writing a research proposal, and later the protocol." },
    { id: 'mf-21-024', module: 21, front: "Primary vs secondary objectives", back: "With many objectives, differentiate them into PRIMARY and SECONDARY (or GENERAL and SPECIFIC) objectives." },
    { id: 'mf-21-025', module: 21, front: "Framing objectives — verbs", back: "Choose appropriate ACTION verbs (e.g. determine, estimate, compare) and avoid broad, vague objectives." },
    { id: 'mf-21-105', module: 21, front: "Objectives — specificity required", back: "Objectives must be SPECIFIC; broad, vague objectives are inappropriate." },
    { id: 'mf-21-026', module: 21, front: "Objectives — link to the gap", back: "Objectives flow logically from the knowledge gap stated in the Background — they state what the study will do to fill it." },
    { id: 'mf-21-027', module: 21, front: "Methods elements — design dependent", back: "The elements of the methods section are adopted according to the STUDY DESIGN chosen (an intervention trial needs different details than a survey)." },
    { id: 'mf-21-028', module: 21, front: "Operational definitions — location (concept paper)", back: "The 'Methodology' (Methods) section contains the key operational definitions." },
    { id: 'mf-21-029', module: 21, front: "Sampling strategy — location", back: "The METHODOLOGY (Methods) section of the concept paper." },
    { id: 'mf-21-030', module: 21, front: "Outcomes — concept paper", back: "It is ESSENTIAL to specify the PRIMARY and SECONDARY outcomes in the methods section of the concept paper." },
    { id: 'mf-21-031', module: 21, front: "Analysis plan — in concept paper Methods", back: "Yes — the Methods section outlines the analysis plan along with design, operational definitions, sampling strategy and outcomes." },
    { id: 'mf-21-032', module: 21, front: "Methods — what it does NOT contain", back: "'Context of study' and the novelty of the study. Methods holds design, operational definitions, sampling strategy, outcomes and the analysis plan." },
    { id: 'mf-21-033', module: 21, front: "'Context of study' — where it belongs", back: "The setting/context of the study belongs in the Background — it is not a Methods element." },
    { id: 'mf-21-034', module: 21, front: "Concept paper for an INTERVENTION study — methods must state", back: "Randomization · sequence allocation · allocation concealment — all three." },
    { id: 'mf-21-035', module: 21, front: "Expected benefits — new information", back: "'Expected Benefits' states what NEW information the study is expected to generate." },
    { id: 'mf-21-036', module: 21, front: "Expected benefits — policy/practice changes", back: "The section describes the POLICY/PRACTICE changes expected through the study results." },
    { id: 'mf-21-037', module: 21, front: "'Agenda for further research' — section", back: "Expected Benefits." },
    { id: 'mf-21-038', module: 21, front: "Expected benefits — what it is NOT", back: "Not financial benefit to the researcher or funding agency, and not academic improvement of the researchers." },
    { id: 'mf-21-039', module: 21, front: "Expected benefits — perspective", back: "Written from the PARTICIPANTS'/community perspective — the benefit to them and to policy/practice." },
    { id: 'mf-21-040', module: 21, front: "Concept paper — ethics section", back: "Key measures to protect participants · information about sample and data storage." },
    { id: 'mf-21-103', module: 21, front: "Concept paper — ethics section and the IEC", back: "The ethics section names the ethics committee to which the study will be submitted for approval." },
    { id: 'mf-21-041', module: 21, front: "Concept paper ethics — what it does NOT include", back: "Salary of the project staff — that is a budget matter, not an ethics matter." },
    { id: 'mf-21-042', module: 21, front: "Concept paper — budget", back: "A summary of the BROAD heads of expenses only — not detailed line items." },
    { id: 'mf-21-043', module: 21, front: "Justifiable budget heads (student thesis)", back: "Salary for data collectors · travel cost for data collection · equipment cost." },
    { id: 'mf-21-044', module: 21, front: "Budget — a non-justifiable head", back: "Remuneration for the thesis guide — paying the guide from a student's study budget is not justified." },
    { id: 'mf-21-045', module: 21, front: "Concept paper — references format", back: "References must follow a STANDARD bibliographic format." },
    { id: 'mf-21-101', module: 21, front: "Concept paper — references and statements", back: "Statements made in the concept paper should be linked to references." },
    { id: 'mf-21-102', module: 21, front: "Concept paper — number of references", back: "A LIMITED number — 'as many references as possible' is wrong." },
    { id: 'mf-21-046', module: 21, front: "Concept paper — reference section status", back: "A standard, non-optional component." },
    { id: 'mf-21-047', module: 21, front: "References — sections where they may be cited", back: "In the Background/Introduction AND the Methods sections — not in the budget." },
    { id: 'mf-21-048', module: 21, front: "Concept paper vs abstract", back: "Both are concise, but an abstract summarises a COMPLETED work, while a concept paper PROPOSES a future study and precedes the protocol." },
    { id: 'mf-21-049', module: 21, front: "Concept paper — basic components (exam favourite)", back: "Study TITLE and REFERENCES are components; an abstract, results and a conclusion are not." },
    { id: 'mf-21-104', module: 21, front: "Sample size — from which objective", back: "Sample size should be calculated from the PRIMARY objective, not the secondary objectives." },
    { id: 'mf-21-050', module: 21, front: "Concept paper — timing", back: "BEFORE the study is conducted and before full protocol drafting — it is the first document funding agencies see and screen." }
  ],

  // ---- Module 22: Elements of a protocol for research studies ----
  22: [
    { id: 'mf-22-001', module: 22, front: "First step for writing a protocol", back: "Identify the TOPIC, the research QUESTION and the OBJECTIVES — before drafting anything else." },
    { id: 'mf-22-002', module: 22, front: "Concept paper as outline", back: "The concept paper can be used as the OUTLINE for drafting the first draft of the protocol." },
    { id: 'mf-22-003', module: 22, front: "First draft — ideal length", back: "The first draft of the protocol ideally should NOT exceed 2000 words." },
    { id: 'mf-22-004', module: 22, front: "Introduction — share of the protocol", back: "The introduction must stay a concise background with justification; it should NOT be 40% of the protocol content." },
    { id: 'mf-22-005', module: 22, front: "Peer review — protocol step", back: "Submitting the draft protocol for peer review is a step in drafting a successful protocol; it improves quality." },
    { id: 'mf-22-006', module: 22, front: "Protocol — requirement for IEC approval", back: "A protocol is a MUST for obtaining ethics committee approval." },
    { id: 'mf-22-007', module: 22, front: "References in a protocol", back: "All known facts stated in the protocol must be supported by appropriate references; the KEY references are cited in the Introduction (Background)." },
    { id: 'mf-22-101', module: 22, front: "Protocol — additional references", back: "Additional references CAN and should be added as the first draft evolves." },
    { id: 'mf-22-008', module: 22, front: "Study population vs study sample", back: "NOT the same — the study sample is the subset of the study population actually selected; the protocol must describe both." },
    { id: 'mf-22-104', module: 22, front: "Study sample — relation to the population", back: "The study sample is drawn from the study population by the stated sampling procedure." },
    { id: 'mf-22-009', module: 22, front: "Inclusion/exclusion criteria — subsection", back: "Under STUDY POPULATION (within Methods), along with how participants will be recruited." },
    { id: 'mf-22-010', module: 22, front: "Recruitment methods — location", back: "Described with the study population (Methods) — how participants will be identified and recruited." },
    { id: 'mf-22-011', module: 22, front: "Sample size — determinants", back: "Decided by the study OBJECTIVES and the SAMPLING method (together with design and expected effect)." },
    { id: 'mf-22-012', module: 22, front: "Number of participants — how decided", back: "By ALL of: pilot study, formal sample-size CALCULATION and the sampling procedure." },
    { id: 'mf-22-013', module: 22, front: "Data quality assurance — location", back: "The PROJECT IMPLEMENTATION section of the protocol." },
    { id: 'mf-22-014', module: 22, front: "Implementation plan — contents", back: "Coordinating project activities · assigning job responsibilities · preparing the project timeline." },
    { id: 'mf-22-015', module: 22, front: "Implementation plan — LEAST appropriate item", back: "Calculating the sample size — that belongs to Methods, not to the implementation plan." },
    { id: 'mf-22-016', module: 22, front: "Project timeline — location", back: "The implementation/management plan section (commonly displayed as a Gantt chart)." },
    { id: 'mf-22-017', module: 22, front: "Data collection paragraph — contents", back: "The KIND of data that will be collected · information about the data collector · the detailed manner in which data will be collected." },
    { id: 'mf-22-018', module: 22, front: "Data collection — what it does NOT specify", back: "How the collected data will be used for POLICY RECOMMENDATIONS — that is not part of the data-collection paragraph." },
    { id: 'mf-22-019', module: 22, front: "Data entry, software, analysis plan — location", back: "METHODS — mode of data entry, software for data analysis and the plan for data analysis." },
    { id: 'mf-22-020', module: 22, front: "Operational definitions — reference support", back: "Operational definitions may be supported by appropriate references." },
    { id: 'mf-22-021', module: 22, front: "Operational definitions — specificity", back: "They must be SPECIFIC — broad and non-specific definitions are wrong; they are not part of the background and do not state research gaps." },
    { id: 'mf-22-022', module: 22, front: "Operational definitions — content", back: "Explain the key OUTCOMES and EXPOSURES — exactly how each variable will be measured in YOUR study." },
    { id: 'mf-22-023', module: 22, front: "Human participant protection (HPP) paragraph — covers", back: "Confidentiality · risks to participants · compensation (e.g. for loss of wages) · procedures for minimizing risk." },
    { id: 'mf-22-102', module: 22, front: "Human participant protection statement — location", back: "Included in the METHODS section of the protocol." },
    { id: 'mf-22-024', module: 22, front: "HPP paragraph — what it does NOT address", back: "Sample-size calculation — that is a Methods matter, not participant protection." },
    { id: 'mf-22-025', module: 22, front: "Risk-minimizing measures — subsection", back: "Methods → Human participant protection — where possible risk-minimizing measures are described." },
    { id: 'mf-22-026', module: 22, front: "Anonymity while sharing data — section", back: "HUMAN SUBJECT PROTECTION — the need to maintain anonymity of participants when sharing data with others." },
    { id: 'mf-22-027', module: 22, front: "Human-subject protection mechanisms", back: "Informed consent · ethics-committee review · compensating participants for loss of wages. INCENTIVIZING the target population is NOT a protection mechanism." },
    { id: 'mf-22-028', module: 22, front: "Description of the intervention — essential for", back: "EXPERIMENTAL studies — the protocol of a trial must describe the intervention in detail." },
    { id: 'mf-22-029', module: 22, front: "Adverse event management plan — location", back: "In an INTERVENTIONAL study, the AE management plan is documented in detail in the METHODS section." },
    { id: 'mf-22-030', module: 22, front: "Toxicity management — annexure", back: "The ADVERSE EVENT MANAGEMENT FORM is the annexure that deals with toxicity management." },
    { id: 'mf-22-031', module: 22, front: "Protocol annexures — examples", back: "Consent forms · toxicity/AE management forms · study management forms · standard operating procedures (SOPs)." },
    { id: 'mf-22-032', module: 22, front: "Budget — location", back: "The BUDGET section describes the key heads of expenses of the study." },
    { id: 'mf-22-033', module: 22, front: "Protocol development — appropriate steps", back: "Development of the research question · preparation of the analysis plan · development of the study tool." },
    { id: 'mf-22-034', module: 22, front: "Protocol development — NOT a step", back: "INITIATION of data collection — data collection starts only after the protocol (and ethics approval) are complete." },
    { id: 'mf-22-035', module: 22, front: "Objectives to indicators — which section guides", back: "The STUDY DESIGN section — it shows how the objectives lead to indicators and what data will answer them." },
    { id: 'mf-22-036', module: 22, front: "Detailed analysis plan — required", back: "YES — it is REQUIRED in a study protocol, written a priori in the Methods section." },
    { id: 'mf-22-103', module: 22, front: "Analysis plan — when written", back: "Written A PRIORI, before data collection begins, as part of the protocol." },
    { id: 'mf-22-037', module: 22, front: "Study design section — sufficient content", back: "Merely stating whether the study is QUANTITATIVE or QUALITATIVE is NOT sufficient — the specific design must be described." },
    { id: 'mf-22-038', module: 22, front: "Willingness of participants — how obtained", back: "By INFORMED CONSENT (not a mere oral commitment; willingness cannot be assumed)." },
    { id: 'mf-22-039', module: 22, front: "Study population — what NOT to include", back: "Salary of study participants — the population description covers inclusion/exclusion criteria and recruitment methods, not payment." },
    { id: 'mf-22-040', module: 22, front: "Expected benefits and the Methods section", back: "NOT a Methods component; Methods holds design, population, tools, quality assurance, data management and the analysis plan." },
    { id: 'mf-22-041', module: 22, front: "Methods — what CAN be included", back: "Analysis plan · supportive references · quality assurance measures." },
    { id: 'mf-22-042', module: 22, front: "Protocol — definition", back: "The DETAILED PLAN for conducting the study, documented in the Methods section (the introduction gives only background)." },
    { id: 'mf-22-043', module: 22, front: "Study procedure — describes", back: "The sequence of what happens to participants: screening → enrollment/consent → intervention/measurement → follow-up." },
    { id: 'mf-22-044', module: 22, front: "Introduction — content", back: "Background WITH JUSTIFICATION — the rationale for the study. Inclusion/exclusion criteria, budget and participant protection do NOT belong here." },
    { id: 'mf-22-045', module: 22, front: "Consent forms — location", back: "As an ANNEXURE to the protocol (participant information and consent forms are attached)." },
    { id: 'mf-22-046', module: 22, front: "Study population — how defined", back: "By demographic/clinical criteria (inclusion/exclusion) AND geographically and temporally — where and when participants will be drawn." },
    { id: 'mf-22-047', module: 22, front: "Data quality assurance — measures", back: "Training of data collectors · supportive supervision · field checks of filled forms · validation against source documents." },
    { id: 'mf-22-048', module: 22, front: "Study tool development — a protocol step", back: "YES — developing the data collection tool (questionnaire/case record form) is an appropriate step of protocol development, before any data collection." },
    { id: 'mf-22-049', module: 22, front: "First draft — references", back: "Additional references CAN and should be added as the first draft evolves." },
    { id: 'mf-22-105', module: 22, front: "Sample size calculation — necessary or not", back: "Sample-size calculation IS necessary for a research study." },
    { id: 'mf-22-050', module: 22, front: "Results — a protocol section", back: "NO — a protocol has no results section (results exist only after the study); standard sections end with budget, references and annexures." }
  ],

  // ---- Module 23: Publication ethics ----
  23: [
    { id: 'mf-23-001', module: 23, front: "Publishing research — career reasons", back: "Academic promotion and career progression, and improving the credibility of the researcher." },
    { id: 'mf-23-101', module: 23, front: "Publishing research — scientific reasons", back: "Communicating findings with peers · identifying research gaps · driving change in practice." },
    { id: 'mf-23-002', module: 23, front: "Negative findings — publication status", back: "They SHOULD be published; suppressing them distorts the evidence base." },
    { id: 'mf-23-003', module: 23, front: "Publication bias", back: "The tendency of studies with positive/significant results to be published more often than studies with negative/null results." },
    { id: 'mf-23-004', module: 23, front: "Research publications — potential readership", back: "Everyone — findings should reach practitioners, policymakers and the public; 'common people should not read them' is FALSE." },
    { id: 'mf-23-005', module: 23, front: "Authorship — what it confers", back: "Credit AND responsibility/accountability for the published work — authorship is not just an honour." },
    { id: 'mf-23-006', module: 23, front: "ICMJE — full form and role", back: "International Committee of Medical Journal Editors — recommends the criteria for authorship." },
    { id: 'mf-23-007', module: 23, front: "Final version approval", back: "MANDATORY — all authors must approve the final version of the manuscript." },
    { id: 'mf-23-008', module: 23, front: "Contribution declaration", back: "It is MANDATORY to declare the contribution of each author in the manuscript." },
    { id: 'mf-23-009', module: 23, front: "Gift/guest author", back: "A person listed as author without meeting the contribution criteria — UNETHICAL; authorship cannot be given at will or gifted." },
    { id: 'mf-23-010', module: 23, front: "Ghost author", back: "Someone who DID substantial work (e.g. writing the manuscript) but is NOT listed as an author — the mirror image of a gift author." },
    { id: 'mf-23-011', module: 23, front: "Head of department and authorship", back: "Being departmental head is NOT a sufficient criterion; authorship follows contribution, not hierarchy." },
    { id: 'mf-23-012', module: 23, front: "Authorship — timing of decision", back: "BEFORE submission to a journal — based on agreed criteria (e.g. ICMJE), never after submission and never by the journal." },
    { id: 'mf-23-013', module: 23, front: "Author order", back: "The sequence reflects the level of contribution (first author = major contributor); it is never fixed alphabetically." },
    { id: 'mf-23-014', module: 23, front: "Financial support alone and authorship", back: "Insufficient — only providing funds does NOT qualify for authorship; funders and non-author helpers are ACKNOWLEDGED instead." },
    { id: 'mf-23-015', module: 23, front: "Acknowledgments — for whom", back: "People who contributed but do not meet all authorship criteria (e.g. funding, technical help, writing assistance) — and unpublished work." },
    { id: 'mf-23-016', module: 23, front: "Unpublished work — acknowledgement", back: "Unpublished work (e.g. personal communications, theses) must be acknowledged in the manuscript." },
    { id: 'mf-23-017', module: 23, front: "Plagiarism — what counts", back: "Copying-and-pasting text from a published manuscript, AND copying someone's IDEA — both are plagiarism, a serious publication misconduct." },
    { id: 'mf-23-018', module: 23, front: "Copying an idea and plagiarism", back: "It IS plagiarism — ideas as well as text require attribution." },
    { id: 'mf-23-019', module: 23, front: "Self-plagiarism", back: "Copying from one's OWN previous work without attribution is also plagiarism." },
    { id: 'mf-23-020', module: 23, front: "Plagiarism — seriousness", back: "It IS a serious publication misconduct — claiming it is minor or trivial is wrong." },
    { id: 'mf-23-021', module: 23, front: "Plagiarism-detection software", back: "e.g. Urkund — used by institutions and journals to check manuscripts for plagiarism." },
    { id: 'mf-23-022', module: 23, front: "Plagiarism — consequences", back: "The journal can RETRACT the article · the author's institute can take action · the researcher loses professional reputation." },
    { id: 'mf-23-023', module: 23, front: "Avoiding plagiarism — measures", back: "Avoid copy-paste · acknowledge/cite original sources · use anti-plagiarism software · cite the reference when using others' content." },
    { id: 'mf-23-024', module: 23, front: "Rephrasing without a reference", back: "NOT enough — rewording someone's content without citing the source is still plagiarism." },
    { id: 'mf-23-025', module: 23, front: "Plagiarism of a research proposal", back: "Submitting a proposal that is a near copy of an earlier proposal (even from the same department) is PLAGIARISM — misconduct applies to proposals too." },
    { id: 'mf-23-026', module: 23, front: "Salami slicing", back: "Splitting ONE comprehensive study into several minimal manuscripts to maximise publication count (e.g. to gain promotion) — a publication misconduct." },
    { id: 'mf-23-027', module: 23, front: "Simultaneous submission", back: "Submitting the same manuscript to more than one journal AT THE SAME TIME — unethical." },
    { id: 'mf-23-102', module: 23, front: "Simultaneous submission vs duplicate publication", back: "Simultaneous = the same manuscript to multiple journals at once. Duplicate = publishing the same work more than once. Both unethical." },
    { id: 'mf-23-028', module: 23, front: "Silent resubmission to another journal", back: "After a long silence (e.g. 5 months) from journal A, submitting to journal B WITHOUT informing A's editor is still SIMULTANEOUS submission." },
    { id: 'mf-23-029', module: 23, front: "Duplicate publication", back: "Publishing the SAME work (substantially) more than once — distinct from simultaneous submission, and equally unethical." },
    { id: 'mf-23-030', module: 23, front: "Correct submission practice", back: "Submit to ONE journal and WAIT for its response — not to multiple journals at once, and not to a second journal after merely a week." },
    { id: 'mf-23-031', module: 23, front: "Conflict of interest — scope", back: "Direct or indirect influence from FINANCIAL, PERSONAL or SOCIAL interests — not always financial — that could bias the work." },
    { id: 'mf-23-032', module: 23, front: "Conflict of interest — disclosure", back: "MUST be disclosed at submission; hiding or suppressing it is wrong even if it has implications for the findings." },
    { id: 'mf-23-033', module: 23, front: "COI — is it always financial", back: "No — conflict of interest is not always financial; personal, professional and social influences count too." },
    { id: 'mf-23-034', module: 23, front: "COI section — why readers check it", back: "To determine the RESEARCHER-LEVEL factors that may have influenced the conclusions of the paper." },
    { id: 'mf-23-035', module: 23, front: "Conflict of interest and misconduct", back: "A conflict of interest itself is NOT publication misconduct — undisclosed COI is the problem; disclosure is the remedy." },
    { id: 'mf-23-036', module: 23, front: "Guest author to improve acceptance", back: "NOT allowed — adding a prestigious/guest author to improve acceptance chances WORSENS publication ethics; it is misconduct, not a remedy." },
    { id: 'mf-23-037', module: 23, front: "Familial ties to the funder", back: "A familial relationship between an author and (e.g.) the CEO of the funding agency must be DECLARED as a conflict of interest." },
    { id: 'mf-23-038', module: 23, front: "Reproducing figures/tables", back: "Obtain PERMISSION from the copyright holder (usually the journal) before reproducing a copyrighted figure or table." },
    { id: 'mf-23-039', module: 23, front: "Journals and CTRI registration", back: "Reputed journals check trial registration and may REJECT an unregistered drug trial; publication without any queries suggests a PREDATORY journal." },
    { id: 'mf-23-040', module: 23, front: "Predatory journals", back: "Journals that publish without proper peer review or ethics/regulatory checks (e.g. never asking about trial registration), usually for a fee." },
    { id: 'mf-23-041', module: 23, front: "Publishing — permitted stages for a researcher", back: "At ALL stages — the protocol, the methodology description, and the conclusions/recommendations can each be published." },
    { id: 'mf-23-042', module: 23, front: "Sharing data for analysis", back: "Seeking help from the mentor or institutional colleagues is fine; sharing participant data with friends from a DIFFERENT institution is NOT advised." },
    { id: 'mf-23-043', module: 23, front: "Publication misconduct — examples", back: "Plagiarism · ghost/gift authorship · data fabrication · data falsification · duplicate or simultaneous submission." },
    { id: 'mf-23-044', module: 23, front: "Retraction", back: "The journal can RETRACT a published article when serious misconduct (e.g. plagiarism) is proven." },
    { id: 'mf-23-045', module: 23, front: "Institutional action on misconduct", back: "The author's institute CAN take action against a researcher found guilty of publication misconduct (e.g. plagiarism)." },
    { id: 'mf-23-046', module: 23, front: "Authorship from thesis work", back: "A co-author (even a spouse or colleague from another department) is justified ONLY if they meet the contribution criteria, e.g. contributed to designing the work." },
    { id: 'mf-23-047', module: 23, front: "Authorship criterion — conception", back: "Conceptualizing the study (conception/design) DOES count toward authorship; administrative headship does not." },
    { id: 'mf-23-048', module: 23, front: "COPE — full form and role", back: "Committee on Publication Ethics — provides guidance and flowcharts for editors/publishers on misconduct such as plagiarism, authorship disputes and retractions." },
    { id: 'mf-23-049', module: 23, front: "Drafting alone and authorship", back: "Not sufficient — drafting is only ONE criterion; ALL four ICMJE criteria must be met for authorship." },
    { id: 'mf-23-050', module: 23, front: "Patient confidentiality in manuscripts", back: "Identifying details of participants must NOT appear in the manuscript (text, tables or images) without consent; confidentiality obligations continue after the study." },
    { id: 'mf-23-103', module: 23, front: "Manipulating data to obtain a significant result", back: "FALSIFICATION — altering/manipulating data; inventing data outright is FABRICATION. Both are publication misconduct." }
  ]
};